Hi!

You are not resetting the variables between looping, i.e.

a = b = c = d = e = 6;

for (; a > 0; a--) {
b=6;
for (; b > 0; b--) {
c=6;
for (; c > 0; c--) {
d=6;
for (; d > 0; d--) {
e=6;
for (; e > 0; e--) {
cout << "a: " << a << " b: " << b << " c: " << c << " d: " << d << " e: " << e << endl;
}
}
}
}
}

