int a, b, c, d, e;for (a = 6; a > 0; a--) {    for (b = 6; b > 0; b--) {        for (c = 6; c > 0; c--) {            for (d = 6; d > 0; d--) {                for (e = 6; e > 0; e--) {                    cout << "a: " << a << " b: " << b << " c: " << c << " d: " << d << " e: " << e << endl;                }            }        }    }}

Regards

