for (int a = 6; a > 0; a--) {	for (int b = 6; b > 0; b--) {		for (int c = 6; c > 0; c--) {			for (int d = 6; d > 0; d--) {				for (int e = 6; e > 0; e--) {					cout << "a: " << a << " b: " << b << " c: " << c << " d: " << d << " e: " << e << endl;				}			}		}	}}

